mapper.sql:
WHERE m.delete_yn = 'N'

  AND m.status = #{search.status}


  AND m.site_id = #{search.siteId}


  AND m.join_type = #{search.joinType}


  AND m.email_hash = #{search.emailExact}


  AND (m.login_id LIKE CONCAT('%', #{search.keyword}, '%')
    OR m.nickname LIKE CONCAT('%', #{search.keyword}, '%'))

mapper.select:
SELECT 
FROM tb_member m
LEFT JOIN tb_site s ON s.site_id = m.site_id
WHERE m.login_id  = #{loginId}

    AND m.site_id = #{siteId}

AND m.delete_yn = 'N'

SELECT FROM tb_member m LEFT JOIN tb_site s ON s.site_id = m.site_id WHERE m.email_hash = #{emailHash}
AND m.site_id = #{siteId}
AND m.delete_yn = 'N' LIMIT 1

SELECT 
FROM tb_member m
LEFT JOIN tb_site s ON s.site_id = m.site_id
WHERE m.email_hash = #{emailHash}

    AND m.site_id = #{siteId}

AND m.login_id   = #{loginId}
AND m.delete_yn  = 'N'
LIMIT 1

SELECT 
FROM tb_member m
LEFT JOIN tb_site s ON s.site_id = m.site_id
WHERE m.email_hash  = #{emailHash}
  AND m.member_name = #{memberName}

    AND m.site_id = #{siteId}

  AND m.delete_yn  = 'N'
LIMIT 1

SELECT COUNT(1) FROM tb_member
WHERE site_id  = #{siteId}
AND login_id = #{loginId}
AND delete_yn = 'N'

    AND member_id <> #{excludeMemberId}

SELECT COUNT(1) FROM tb_member
 WHERE email_hash = #{emailHash}
   AND delete_yn  = 'N'

  AND member_id <> #{excludeMemberId}

mapper.update:
UPDATE tb_member
   SET captcha_required_yn = #{yn}
 WHERE login_id = #{loginId}
   AND delete_yn = 'N'

mapper.select:
SELECT password_hash
  FROM tb_member_password_history
 WHERE member_id = #{memberId}
 ORDER BY changed_at DESC
 LIMIT #{limit}

mapper.delete:
DELETE FROM tb_member
WHERE delete_yn = 'Y'
AND updated_at <= #{cutoff}

mapper.select:
SELECT COUNT(*) FROM tb_member
WHERE delete_yn = 'Y'
AND updated_at <= #{cutoff}

SELECT COUNT(*)
  FROM tb_member_withdraw
 WHERE retention_expire_at <= #{now}
